// Flatten each lead into a flat row: join array fields into strings so they fit a single Sheet cell, and carry the niche/location through from the parent payload.
const niche = $('Wait For Scrape Result').first().json.body.niche;
const location = $('Wait For Scrape Result').first().json.body.location;

return items.map(item => {
  const l = item.json;
  return {
    json: {
      niche,
      location,
      source: l.source || '',
      name: l.name,
      phone: l.phone,
      email: l.email || '',
      website: l.website || '',
      address: l.address,
      category: l.category,
      rating: l.rating,
      review_count: l.review_count,
      lead_score: l.lead_score,
      website_intent_score: l.website_intent_score,
      other_intents: Array.isArray(l.other_intents) ? l.other_intents.join(' | ') : (l.other_intents || ''),
      intent_notes: l.intent_notes,
      ad_status: l.ad_status,
      ad_start_date: l.ad_start_date || '',
      ad_running_days: l.ad_running_days,
      dm_order_flow: l.dm_order_flow,
      checkout_present: l.checkout_present,
      owner_response_ratio: l.owner_response_ratio,
      cid: l.cid,
      maps_url: l.maps_url,
      scraped_at: new Date().toISOString()
    }
  };
});

// Keep only rows matching this request's niche (and location, if you track leads per-location), then return just the cid column.
const niche = $('Seen Leads Webhook').first().json.query.niche;
const location = $('Seen Leads Webhook').first().json.query.location;

const ids = items
  .filter(i => i.json.niche === niche && (!location || i.json.location === location))
  .map(i => String(i.json.cid))
  .filter(Boolean);

return [{ json: { seen_ids: [...new Set(ids)] } }];

// Build a tailored prompt from THIS business's own signals — no generic template text,
// Gemini writes the actual message content from what the scraper found.
const l = $json;

const prompt = `You are writing a first-contact WhatsApp message on behalf of Wenlinco, a South African web design and digital marketing agency, reaching out to a local business that does not currently have a real website.

Business details:
- Name: ${l.name}
- Category: ${l.category}
- Niche searched: ${l.niche}
- Location: ${l.location}
- Website intent score (1-10, how likely they need a website): ${l.website_intent_score}
- Suggested other services: ${l.other_intents}
- Signals noticed: ${l.intent_notes}
- Currently running Meta ads: ${l.ad_status}${l.ad_running_days ? ' (' + l.ad_running_days + ' days)' : ''}
- Sells informally via DM/WhatsApp: ${l.dm_order_flow}

Write a SHORT WhatsApp opening message (2-4 sentences max) that:
- Sounds like a real person messaging them, not a mass broadcast
- Mentions something SPECIFIC and true about their business from the signals above — never invent details not given
- Briefly introduces Wenlinco and the ONE most relevant service angle based on the signals
- Ends with a low-pressure, easy-to-answer question, not a hard sell
- Uses at most one emoji, optional
- Friendly, professional South African tone

Respond with ONLY valid JSON, no markdown fences, in this exact shape:
{"message": "the message text", "angle": "a short phrase naming which service angle you used, e.g. 'website + ads funnel' or 'whatsapp ordering automation'"}`;

return { json: { ...l, gemini_prompt: prompt } };

// Pull the original lead fields back from the prompt-building step (the HTTP Request node's
// output only contains Gemini's response, not our lead data), parse Gemini's JSON reply,
// and build the tap-to-send wa.me link.
const original = $('Build Gemini Prompt').item.json;
const geminiResponse = $json;

let raw = '';
try {
  raw = geminiResponse.candidates[0].content.parts[0].text || '';
} catch (e) {
  raw = '';
}
raw = raw.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();

let parsed = { message: '', angle: '' };
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { message: raw, angle: 'unparsed' };
}

const digitsOnly = (original.phone || '').replace(/[^\d]/g, '');
const waLink = digitsOnly
  ? `https://wa.me/${digitsOnly}?text=${encodeURIComponent(parsed.message || '')}`
  : '';

const { gemini_prompt, ...cleanOriginal } = original;

return {
  json: {
    ...cleanOriginal,
    whatsapp_message: parsed.message || '',
    message_angle: parsed.angle || '',
    wa_link: waLink,
  }
};
